import numpy as np
ink = np.load(r"work/ink.npy"); b = (ink > 8).astype(float)

def lines(y0, y1, x0, x1, thr=0.45):
    proj = b[y0:y1, x0:x1].mean(axis=1)
    groups = []; cur = []
    for i, v in enumerate(proj):
        if v > thr:
            if cur and i - cur[-1][0] > 2: groups.append(cur); cur = []
            cur.append((i, v))

    if cur: groups.append(cur)
    cents = [sum((i + y0) * v for i, v in g) / sum(v for i, v in g) for g in groups]
    return cents

